INSERT INTO `culture_imageblock` VALUES (8772,'culture/images/maharashtra/pune/cultural-sites/front-view-of-the-aga-khan-palace-kalyani_0Cd6igl.jpg','Front view of the Aga Khan Palace, Kalyani Nagar, Pune, showcasing its Indo-Saracenic design and landscaped gardens. (Source: CKA Archives)','Front view of the Aga Khan Palace, Kalyani Nagar, Pune, showcasing its Indo-Saracenic design and landscaped gardens. (Source: CKA Archives)',NULL),(8774,'culture/images/maharashtra/pune/cultural-sites/the-samadhis-of-mahatma-gandhi-l-kasturba_XPHpC1J.jpg','The Samadhis of Mahatma Gandhi (L), Kasturba Gandhi and Mahadev Desai in Aga Khan Palace, Kalyani Nagar, Pune. (Source: CKA Archives)','The Samadhis of Mahatma Gandhi (L), Kasturba Gandhi and Mahadev Desai in Aga Khan Palace, Kalyani Nagar, Pune. (Source: CKA Archives)',NULL),(8776,'culture/images/maharashtra/pune/cultural-sites/display-board-offering-insights-into-the-_0vT17vN.jpg','Display board offering insights into the political climate of 1942 and the significance of the palace as a site of resistance. (Source: CKA Archives)','Display board offering insights into the political climate of 1942 and the significance of the palace as a site of resistance. (Source: CKA Archives)',NULL),(8778,'culture/images/maharashtra/pune/cultural-sites/the-anterior-view-of-the-aga-khan-palace-_ZPl5Lg5.jpg','The anterior view of the Aga Khan Palace. (Source: CKA Archives)','The anterior view of the Aga Khan Palace. (Source: CKA Archives)',NULL),(8780,'culture/images/maharashtra/pune/cultural-sites/the-corridor-of-the-aga-khan-palace-sourc_oLrQRRX.jpg','The corridor of the Aga Khan Palace. (Source: CKA Archives)','The corridor of the Aga Khan Palace. (Source: CKA Archives)',NULL),(8782,'culture/images/maharashtra/pune/cultural-sites/room-where-sarojini-naidu-was-held-during_MLnAhjF.jpg','Room where Sarojini Naidu was held during her internment at the Aga Khan Palace alongside Mahatma Gandhi. Notably, the interiors of the Aga Khan Palace have 