--
-- Table structure for table `editor_suggestedit`
--

DROP TABLE IF EXISTS `editor_suggestedit`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `editor_suggestedit` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `name` varchar(255) NOT NULL,
  `email` varchar(254) NOT NULL,
  `app_label` varchar(50) NOT NULL,
  `chapter_id` int unsigned NOT NULL,
  `section` varchar(255) NOT NULL,
  `edit_type` varchar(20) NOT NULL,
  `current_text` longtext NOT NULL,
  `suggested_text` longtext NOT NULL,
  `reason` longtext NOT NULL,
  `sources` longtext NOT NULL,
  `supporting_file` varchar(100) DEFAULT NULL,
  `notify_on_review` tinyint(1) NOT NULL,
  `status` varchar(20) NOT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `review_notes` longtext NOT NULL,
  `reviewed_by_id` int DEFAULT NULL,
  `user_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `editor_suggestedit_reviewed_by_id_0025a60b_fk_auth_user_id` (`reviewed_by_id`),
  KEY `editor_suggestedit_user_id_9ec5a30d_fk_auth_user_id` (`user_id`),
  CONSTRAINT `editor_suggestedit_reviewed_by_id_0025a60b_fk_auth_user_id` FOREIGN KEY (`reviewed_by_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `editor_suggestedit_user_id_9ec5a30d_fk_auth_user_id` FOREIGN KEY (`user_id`) REFERENCES `auth_user` (`id`),
  CONSTRAINT `editor_suggestedit_chk_1` CHECK ((`chapter_id` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
