INSERT INTO `editor_suggestedit` VALUES (1,'Vaibhav Nagargoje','vaibhav@gmail.com','culture',127,'economy','correction','dfsg','dfsgdfg','fgdsg','sdfg','',1,'pending','2025-07-29 16:25:12.778088','2025-07-29 16:25:12.778107','',NULL,1),(2,'Vaibhav Nagargoje','vaibhav@gmail.com','culture',267,'traditional-and-modern-eating-practices','addition','only for testing ','dklfjaslkd fasdkfjasldkfjklasdfasdfadsfas','asfasfasdfasdfasf','ad','suggest_edits/image11.jpg',1,'pending','2025-07-29 17:00:54.561482','2025-07-29 17:00:54.561519','',NULL,1);
